function shuffleList(items){
 const out=[...items];
 for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}
 return out;
}
function balancedStartFeed(){
 // Alle acht Themen erscheinen mindestens dreimal, sechs Themen viermal.
 // Die Themenreihenfolge wechselt in jeder Acht-Gruppe und verhindert Klumpen.
 const more=new Set(shuffleList(TOPICS.map(t=>t.id)).slice(0,6));
 const perTopic=Object.fromEntries(TOPICS.map(t=>[t.id,shuffleList(POSTERS.filter(p=>p.topic===t.id))]));
 const result=[];
 for(let wave=0;wave<4;wave++){
  const topics=shuffleList(TOPICS.map(t=>t.id).filter(id=>wave<3||more.has(id)));
  topics.forEach(id=>result.push(perTopic[id][wave].id));
 }
 if(result.length!==BASELINE_FEED_SIZE||new Set(result).size!==BASELINE_FEED_SIZE)throw Error('Startfeed nicht ausgewogen');
 return result;
}
function initialState(){
 const weights=Object.fromEntries(TOPICS.map(t=>[t.id,1]));
 const initialPosts=balancedStartFeed();
 return {weights,subWeights:{},signals:[],watchData:{},commentWatchData:{},round:1,view:'feed',selected:new Set(),likes:new Set(),saves:new Set(),shares:new Set(),skips:new Set(),posts:initialPosts,feedIds:[...initialPosts],shownPosts:new Set(initialPosts),feedExhausted:false,feedComplete:false,personalizedIds:[],firstDist:distribution(initialPosts),previousDist:distribution(initialPosts),currentDist:distribution(initialPosts),roundHistory:[distribution(initialPosts)],expanded:new Set(),achieved:false,exploredTopics:new Set(),discoveredPosts:new Set(),observation:{answer:'',notes:'',done:false},mission:{phase:'setup',answers:{profile:'',signal:'',transfer:''}}};
}
function distribution(ids){const d=Object.fromEntries(TOPICS.map(t=>[t.id,0]));ids.forEach(id=>{const p=POSTERS.find(p=>p.id===id);if(p)d[p.topic]++});return d;}
function percent(n,total){return total?Math.round(100*n/total):0}
function scoreSum(){return TOPICS.reduce((a,t)=>a+Math.max(.1,state.weights[t.id]),0)}
function weightPct(id){return percent(Math.max(.1,state.weights[id]),scoreSum())}
function distinctCount(){return Object.values(state.currentDist).filter(x=>x>0).length}
function topShare(){return Math.max(...Object.values(state.currentDist))/state.posts.length}
function showToast(msg,early=false){if(!sessionStarted||(!early&&!state.observation.done))return;const el=document.getElementById('toast');el.innerHTML=`<div class="toast">${msg}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.innerHTML=''},2800);}
function recordSignal(topic,type,points,source='feed',subtopic=null,postId=null){
 applyInterestSignal(state,topic,points,subtopic);
 state.signals.push({topic,subtopic,postId,type,points,source,round:state.round});
 updateSide();
 if(state.signals.length===4)showToast('🧠 Dein Algorithmus hat erste Interessen erkannt!');
}
function applyInterestSignal(profile,topic,points,subtopic){
 // Interessen an Unterthemen beeinflussen die Empfehlungen stärker als bloße Oberkategorien.
 const topicDelta=subtopic?points*.65:points;
 profile.weights[topic]=Math.max(.1,profile.weights[topic]+topicDelta);
 if(subtopic){
   const key=`${topic}|${subtopic}`;
   profile.subWeights[key]=Math.max(-6,(profile.subWeights[key]||0)+points);
 }
}
function recordPostSignal(post,type,points,source='feed'){recordSignal(post.topic,type,points,source,post.subtopic,post.id);}
function subtopicName(key){
 const [topic,sub]=key.split('|');const p=POSTERS.find(p=>p.topic===topic&&p.subtopic===sub);
 return p?p.sub:sub;
}
function weightedChoice(items,score,random=Math.random){
 const weights=items.map(item=>Math.max(.01,score(item)));
 const total=weights.reduce((a,b)=>a+b,0);
 let draw=random()*total;
 for(let i=0;i<items.length;i++){draw-=weights[i];if(draw<=0)return items[i];}
 return items[items.length-1];
}
function recommendationScore(p,profile=state){
 const parent=Math.pow(Math.max(.12,profile.weights[p.topic]),1.28);
 const detail=profile.subWeights[`${p.topic}|${p.subtopic}`]||0;
 const interest=Math.pow(Math.max(.12,1+detail*.70),1.25);
 return parent*interest;
}
function recommend(excludeIds=[],onlyUnseen=false,count=FEED_BATCH_SIZE,exploration=0){
 const ids=[];
 const excluded=new Set(excludeIds);
 for(let i=0;i<count;i++){
  const pool=POSTERS.filter(p=>!ids.includes(p.id)&&!excluded.has(p.id)&&(!onlyUnseen||!state.shownPosts.has(p.id)));
  if(!pool.length)break;
  let candidate;
  // Jede sechste Empfehlung ermoeglicht gezielt eine andere Perspektive.
  // Die anderen fuenf folgen den individuellen Themen-/Unterthemenwerten.
  if(exploration&&i===count-1){
   const weakTopics=[...TOPICS].sort((a,b)=>state.weights[a.id]-state.weights[b.id]).slice(0,4).map(t=>t.id);
   const options=pool.filter(p=>weakTopics.includes(p.topic));
   candidate=shuffleList(options.length?options:pool)[0];
  }else{
   candidate=weightedChoice(pool,recommendationScore);
  }
  ids.push(candidate.id);
 }
 return exploration?shuffleList(ids):ids;
}
