  document.querySelectorAll('[data-nav]').forEach(btn=>{const on=btn.dataset.nav===state.view;btn.classList.toggle('selected',on);btn.classList.toggle('active',on);});
  stopAllWatches();if(observer)observer.disconnect();observer=null;
