function appendFeedBatch(){
 const stack=document.getElementById('feedStack');
 if(!stack||state.feedComplete)return;
 const pending=PERSONAL_TOTAL-state.personalizedIds.length;
 if(pending<=0)return;
 const batch=recommend(state.feedIds,true,Math.min(PERSONAL_BATCH_SIZE,pending),1);
 if(!batch.length)return;
 state.previousDist={...state.currentDist};
 state.round++;
 batch.forEach(id=>state.shownPosts.add(id));
 state.personalizedIds.push(...batch);
 state.posts=[...state.personalizedIds]; // Analyse: Gesamtheit der empfohlenen 18, nicht nur letzte 6.
 state.currentDist=distribution(state.personalizedIds);
 state.roundHistory.push({...state.currentDist});
 state.feedIds.push(...batch);
 const template=document.createElement('template');
 template.innerHTML=batch.map(id=>renderPost(getPost(id))).join('');
 const newMedia=[...template.content.querySelectorAll('[data-watch-media]')];
 stack.appendChild(template.content);
 if(observer)newMedia.forEach(el=>observer.observe(el));
 scanVisiblePosts();
 if(state.personalizedIds.length>=PERSONAL_TOTAL){
  document.getElementById('feedLoadSentinel').innerHTML=feedEndMarker();
  disconnectInfiniteScroll();
  observeInfiniteScroll();
 }
}
function trimOldFeedCards(stack){
 const removeCount=Math.max(0,stack.children.length-MAX_FEED_CARDS);
 if(!removeCount)return;
 // Die alten Posts werden nur ganz oben entfernt; Scrollposition anpassen,
 // damit das Nachladen nicht zu einem sichtbaren Seitensprung führt.
 const kept=stack.children[removeCount];
 const before=kept.getBoundingClientRect().top;
 for(let i=0;i<removeCount;i++){
  const card=stack.firstElementChild;
  const id=card?.dataset.post;
  if(id){
   const media=card.querySelector('[data-watch-media]');
   if(observer&&media)observer.unobserve(media);
   stopWatching(id,false);
  }
  card.remove();
 }
 state.feedIds=[...stack.querySelectorAll('[data-post]')].map(el=>el.dataset.post);
 const delta=kept.getBoundingClientRect().top-before;
 if(delta)window.scrollBy({top:delta,left:0,behavior:'instant'});
}
