function tickSingleWatch(id,active,now){
 const w=watchInfo(id);
 const delta=Math.max(0,Math.min(300,now-active.lastTime));
 active.lastTime=now;
 w.ms+=delta;active.sessionMs+=delta;
 const p=getPost(id);
 if(!p)return;
 if(!w.three&&w.ms>=3000){w.three=true;recordPostSignal(p,'3 Sekunden betrachtet',1,state.view==='discover'?'discover':'feed');showToast('👀 3 Sekunden betrachtet – als Signal erkannt');}
 if(!w.five&&w.ms>=5000){w.five=true;recordPostSignal(p,'5 Sekunden betrachtet (zusätzlich +1, insgesamt +2)',1,state.view==='discover'?'discover':'feed');showToast('👀 5 Sekunden betrachtet – stärkeres Signal erkannt');}
 if(active.returnVisit&&!w.rewatched&&active.sessionMs>=1500){
   w.rewatched=true;recordPostSignal(p,'Erneut angesehen',2,state.view==='discover'?'discover':'feed');
   showToast('🔁 Erneutes Ansehen erkannt');
 }
 updateWatchLabel(id);
}
function tickVisiblePosts(){
 if(document.hidden||state.view!=='feed'||document.getElementById('modalRoot').hasChildNodes())return;
 const now=performance.now();
 for(const [id,active] of activeWatches){if(!active.element.isConnected){activeWatches.delete(id);continue;}tickSingleWatch(id,active,now);}
}
function startWatching(id,element){
 if(document.hidden||state.view!=='feed'||document.getElementById('modalRoot').hasChildNodes())return;
 const existing=activeWatches.get(id);
 if(existing){existing.element=element;return;}
 const w=watchInfo(id);
 const now=performance.now();
 const revisit=w.three&&w.lastExit!==null&&(now-w.lastExit)>=1100&&!w.rewatched;
 w.sessions++;
 activeWatches.set(id,{element,lastTime:now,sessionMs:0,returnVisit:revisit});
}
function stopWatching(id,allowRewatch=true){
 const active=activeWatches.get(id);
 if(!active)return;
 if(!document.hidden&&state.view==='feed'&&!document.getElementById('modalRoot').hasChildNodes())tickSingleWatch(id,active,performance.now());
 watchInfo(id).lastExit=allowRewatch?performance.now():null;
 activeWatches.delete(id);
}
function stopAllWatches(){for(const id of [...activeWatches.keys()])stopWatching(id,false);if(watchInterval!==null){clearInterval(watchInterval);watchInterval=null;}}
function mediaVisibleRatio(element){
 const rect=element.getBoundingClientRect();
 const w=Math.max(0,Math.min(rect.right,innerWidth)-Math.max(rect.left,0));
 const h=Math.max(0,Math.min(rect.bottom,innerHeight)-Math.max(rect.top,0));
 return rect.width*rect.height>0?w*h/(rect.width*rect.height):0;
}
function scanVisiblePosts(){
 if(state.view!=='feed')return;
 document.querySelectorAll('[data-watch-media]').forEach(el=>{
   const id=el.dataset.watchMedia;
   if(mediaVisibleRatio(el)>=VIEW_MIN_RATIO&&!document.hidden&&!document.getElementById('modalRoot').hasChildNodes())startWatching(id,el);
   else stopWatching(id);
 });
}
function watchVisiblePosts(){
 if('IntersectionObserver' in window){
   observer=new IntersectionObserver(entries=>{
     for(const e of entries){
       const id=e.target.dataset.watchMedia;
       const current=activeWatches.get(id);
       if(current&&current.element!==e.target)continue; // Alter DOM-Knoten nach Re-Render
       if(e.isIntersecting&&e.intersectionRatio>=VIEW_MIN_RATIO)startWatching(id,e.target);
       else stopWatching(id);
     }
   },{threshold:[0,.15,.55,.85]});
   document.querySelectorAll('[data-watch-media]').forEach(el=>observer.observe(el));
 }
 scanVisiblePosts();
 watchInterval=setInterval(()=>{
   if(!('IntersectionObserver' in window))scanVisiblePosts();
   tickVisiblePosts();
 },160);
}

function startModalWatch(id){
 stopModalWatch();
 const element=document.querySelector(`#modalRoot [data-watch-media="${id}"]`);
 if(!element)return;
 const w=watchInfo(id),now=performance.now();
 const revisit=w.three&&w.lastExit!==null&&(now-w.lastExit)>=1100&&!w.rewatched;
 w.sessions++;
 modalWatch={id,element,lastTime:now,sessionMs:0,returnVisit:revisit};
 modalWatchInterval=setInterval(()=>{
   if(!modalWatch)return;
   const current=performance.now();
   if(document.hidden||!modalWatch.element.isConnected||mediaVisibleRatio(modalWatch.element)<VIEW_MIN_RATIO){modalWatch.lastTime=current;return;}
   tickSingleWatch(modalWatch.id,modalWatch,current);
 },160);
}
function stopModalWatch(){
 if(modalWatchInterval!==null){clearInterval(modalWatchInterval);modalWatchInterval=null;}
 if(modalWatch){
   if(!document.hidden&&modalWatch.element.isConnected&&mediaVisibleRatio(modalWatch.element)>=VIEW_MIN_RATIO){tickSingleWatch(modalWatch.id,modalWatch,performance.now());}
   watchInfo(modalWatch.id).lastExit=performance.now();
   modalWatch=null;
 }
}
function performAction(action,id){
 const p=getPost(id);if(!p)return;
 const source=state.view==='discover'?'discover':'feed';
 if(action==='like'){
  const yes=!state.likes.has(id);yes?state.likes.add(id):state.likes.delete(id);
  recordPostSignal(p,yes?'Like':'Like rückgängig',yes?3:-3,source);syncPost(id);
  if(yes)showToast('❤️ Like registriert: '+p.sub);
 }
 if(action==='save'){
  const yes=!state.saves.has(id);yes?state.saves.add(id):state.saves.delete(id);
  recordPostSignal(p,yes?'Speichern':'Speichern rückgängig',yes?4:-4,source);syncPost(id);
  if(yes)showToast('🔖 Speichern registriert: '+p.sub);
 }
 if(action==='share'){
  if(!state.shares.has(id)){state.shares.add(id);recordPostSignal(p,'Teilen (simuliert)',3,source);showToast('↗ Teilen als Signal registriert');}
  else showToast('Diesen Beitrag hast du bereits geteilt.');
 }
 if(action==='skip'){
  if(state.skips.has(id))return;
  stopWatching(id,false);
  state.skips.add(id);recordPostSignal(p,'Weniger davon',-3,source);
  const el=document.querySelector(`[data-post="${id}"]`);
  if(el){if(observer){const media=el.querySelector('[data-watch-media]');if(media)observer.unobserve(media);}el.classList.add('skipping');setTimeout(()=>el.remove(),230);}
  showToast('↘ Weniger davon registriert: '+p.sub);
 }
 if(action==='comments')openComments(p);
 if(action==='expand'){state.expanded.add(id);syncPost(id);}
}
function syncPost(id){
 const el=document.querySelector(`[data-post="${id}"]`);if(!el)return;
 const oldMedia=el.querySelector('[data-watch-media]');
 if(observer&&oldMedia)observer.unobserve(oldMedia);
 el.outerHTML=renderPost(getPost(id));
 const newer=document.querySelector(`[data-post="${id}"] [data-watch-media]`);
 const active=activeWatches.get(id);
 if(active&&newer){active.element=newer;active.lastTime=performance.now();}
 if(observer&&newer)observer.observe(newer);
 updateWatchLabel(id);
}
function renderDiscover(){
 const filter=selectedTopic==='all'?TOPICS:TOPICS.filter(t=>t.id===selectedTopic);
 const m=state.mission;
 const missionHint=m.phase==='experiment'?`<div class="mission-topline"><span>🔬 Dein Experiment läuft: <strong>${topicName(m.target)}</strong></span><button class="outline-btn" data-nav="challenge" type="button">Zur Mission</button></div>`:'';
 feedContainer.innerHTML=`<section class="section-page"><div class="kicker">NEUE PERSPEKTIVEN · ENTDECKEN</div><h1>Entdecke etwas anderes.</h1><p class="lead">Nicht jeder interessante Post landet von selbst im Feed. Erkunde Themen, die dir selten vorgeschlagen werden. Dein Verhalten verändert das Lernmodell.</p>${missionHint}<div class="pills"><button type="button" class="pill ${selectedTopic==='all'?'active':''}" data-filter="all">Alle Themen</button>${TOPICS.map(t=>`<button type="button" class="pill ${selectedTopic===t.id?'active':''}" data-filter="${t.id}">${t.emoji} ${t.short}</button>`).join('')}</div><div class="discover-list">${filter.map(t=>`<article class="disco-card"><img src="assets/${t.covers[1]}" alt="KI-generiertes Motiv aus dem Themenbereich ${t.label}" loading="lazy"/><div class="disco-content"><strong>${t.emoji} ${t.label}</strong><p>In diesem Thema warten mehrere neue Posts auf dich.</p><button class="outline-btn" type="button" data-action="explore" data-topic="${t.id}" ${state.exploredTopics.has(t.id)?'disabled':''}>${state.exploredTopics.has(t.id)?'✓ Interesse gezeigt':'Thema bewusst entdecken'}</button></div></article>`).join('')}</div>${selectedTopic!=='all'?`<div class="discover-posts"><h2>Beiträge aus ${topicName(selectedTopic)}</h2><p>Öffne einen Beitrag, like oder speichere ihn. Beobachte später, ob sich deine Empfehlungen verändern.</p><div class="discover-post-grid">${POSTERS.filter(p=>p.topic===selectedTopic).map(p=>`<button class="discover-post-tile" data-action="explore-post" data-id="${p.id}" type="button"><img src="${p.image}" loading="lazy" alt="${p.category}: ${p.sub}"/><span>${state.likes.has(p.id)?'♥':''} ${state.saves.has(p.id)?'🔖':''}</span></button>`).join('')}</div></div>`:''}<div class="callout" style="margin-top:18px">Hinweis: Die Interessen werden nur in dieser geöffneten Sitzung verarbeitet. Beim Neuladen oder Schließen beginnt alles wieder bei null.</div></section>`;
}
function renderInsights(){
 const total=state.signals.length;
 const sorted=[...TOPICS].sort((a,b)=>state.weights[b.id]-state.weights[a.id]);
 const top=sorted[0], topSub=Object.entries(state.subWeights).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1])[0];
 const current=distribution(state.personalizedIds), initial=state.firstDist;
 const baselineN=Object.values(initial).reduce((a,b)=>a+b,0);
 const currentN=Object.values(current).reduce((a,b)=>a+b,0);
 const dw3=state.signals.filter(s=>s.type==='3 Sekunden betrachtet').length;
 const dw5=state.signals.filter(s=>s.type.startsWith('5 Sekunden betrachtet')).length;
 const repeat=state.signals.filter(s=>s.type==='Erneut angesehen').length;
 const liked=state.signals.filter(s=>s.type==='Like').length;
 const saved=state.signals.filter(s=>s.type==='Speichern').length;
 const reduced=state.signals.filter(s=>s.type==='Weniger davon').length;
 const com3=state.signals.filter(s=>s.type==='Kommentare 3 Sekunden angesehen').length;
 const com5=state.signals.filter(s=>s.type.startsWith('Kommentare 5 Sekunden')).length;
 const sortSubs=Object.entries(state.subWeights).filter(([,v])=>v>.05).sort((a,b)=>b[1]-a[1]).slice(0,6);
 const subMax=Math.max(1,...sortSubs.map(([,v])=>v));
 const interestText=total===0?'Du hast noch keine bewertbaren Signale gesendet. Scrolle, bleibe bei interessanten Beiträgen stehen oder interagiere bewusst.':`Dein Modell vermutet momentan das stärkste Interesse an ${top.emoji} ${top.label}${topSub?`, insbesondere ${subtopicName(topSub[0])}`:''}. Das ist eine Interpretation deiner Aktionen, keine sichere Aussage über deine Persönlichkeit.`;
 const topSignals=[['👀 3 Sekunden',dw3],['👀 5 Sekunden',dw5],['🔁 Wiederholt',repeat],['❤️ Likes',liked],['🔖 Gespeichert',saved],['💬 Kommentare 3 s',com3],['💬 Kommentare 5 s',com5],['↘ Weniger',reduced]];
 const columns=TOPICS.map((t,i)=>{
   const b=percent(initial[t.id],baselineN),n=percent(current[t.id],currentN);
   return `<div class="column-item" style="--delay:${i*75}ms"><div class="column-values">${n} %</div><div class="column-towers"><div class="column-bar before" style="--bar-h:${b}%" role="img" aria-label="${t.label} im Startfeed: ${b} Prozent"></div><div class="column-bar current" style="--bar-h:${n}%" role="img" aria-label="${t.label} in den personalisierten Empfehlungen: ${n} Prozent"></div></div><span class="column-title">${t.emoji}<br>${t.short}</span></div>`;
 }).join('');
 const subbars=sortSubs.map(([key,score])=>{
   const t=TOPICS.find(t=>t.id===key.split('|')[0]);
   return `<div class="sub-interest"><span>${t.emoji} ${subtopicName(key)}</span><div class="track"><div style="width:${Math.round(score/subMax*100)}%"></div></div><b>${Math.round(score*10)/10}</b></div>`;
 }).join('')||'<p>Nach einigen Interaktionen erkennst du hier konkrete Unterinteressen, zum Beispiel Katzen statt nur Tiere.</p>';
 const timeline=state.signals.slice(-12).reverse().map(s=>`<div class="timeline-item"><span class="tag">${s.points>0?'↗':s.points<0?'↘':'•'}</span><span>${s.type}</span><small>${topicEmoji(s.topic)} ${s.subtopic?subtopicName(`${s.topic}|${s.subtopic}`):topicName(s.topic)}</small></div>`).join('')||'<p>Es wurden noch keine Signale registriert.</p>';
 feedContainer.innerHTML=`<section class="section-page"><div class="kicker">LEVEL 3 · DEINE PERSÖNLICHE AUSWERTUNG</div><h1>Was hat dein Feed über dich gelernt?</h1><p class="lead">Diese Ergebnisse wurden ausschließlich aus <strong>deinen eigenen Aktionen in dieser Sitzung</strong> berechnet. Andere Schüler*innen sehen andere Auswertungen.</p>
 <div class="hero-panel"><span class="kicker" style="color:#d7f9f6">DEIN SIMULIERTES INTERESSENPROFIL</span><h2>${total?top.emoji+' '+top.label:'Noch offen: Deine Interessen'}</h2><p>${interestText}</p></div>
 <div class="stat-grid" style="margin-top:15px"><div class="stat"><div class="number">${total}</div><small>Erfasste Signale</small></div><div class="stat"><div class="number">${state.round}</div><small>Feed-Runden</small></div><div class="stat"><div class="number">${distinctCount()} / ${TOPICS.length}</div><small>Themen im Feed</small></div></div>
 <div class="panel"><h2>Themenanteile im Feed</h2><p><strong>Dein erster Eindruck:</strong> ${OBSERVATION_CHOICES[state.observation.answer]||''}</p><p><strong>Deine Beobachtung zu den Themen, die dich interessiert haben:</strong> ${esc(state.observation.notes)}</p><p>Wähle ein Thema und vergleiche seine Anteile im Startfeed und in den Empfehlungen. Welche Zahl stützt deine Beobachtung oder widerspricht ihr? Welches Signal könnte zur Veränderung beigetragen haben?</p><p>Die Säulen wachsen beim Öffnen von unten nach oben: <strong>Grau = 30 gemischte Startbeiträge</strong>, <strong>Türkis = 18 personalisierte Empfehlungen</strong>. Ein Themenanteil zeigt, wie viele der ausgewählten Beiträge zu einem Thema gehören. Beispiel: 3 von 18 Empfehlungen entsprechen gerundet 17 %.</p><div class="chart-legend"><span><i class="swatch grey"></i> Startfeed</span><span><i class="swatch violet"></i> Personalisierte Empfehlungen</span></div><div class="columns-scroll"><div class="columns-chart" role="group" aria-label="Animiertes Säulendiagramm: Themenverteilung Startfeed und aktueller Feed"><div class="chart-grid-lines"><span>100 %</span><span>75 %</span><span>50 %</span><span>25 %</span><span>0 %</span></div><div class="columns-content">${columns}</div></div></div><p class="hint-note">Bei dir können andere Ergebnisse entstehen. Da die Empfehlung eine gewichtete Zufallsauswahl verwendet, sind einzelne Feed-Runden nicht vollständig vorhersehbar.</p></div>
 <div class="panel"><h2>Welche Handlungen hast du ausgeführt?</h2><div class="signal-matrix">${topSignals.map(([label,count])=>`<div class="signal-cell"><strong>${count}</strong><span>${label}</span></div>`).join('')}</div><p>Auch die Verweildauer und das Lesen von Kommentarbereichen beeinflussen die Simulation. Nicht nur Likes oder Speicheraktionen zählen. <strong>Hinweis:</strong> Ein fünf Sekunden lang betrachteter Post wird auch in der Anzahl der Drei-Sekunden-Signale mitgezählt.</p></div>
 <div class="panel"><h2>Interne Interessenwerte für Unterthemen</h2><p>Das System unterscheidet Unterthemen wie Katzen, Hunde, Horror, Comedy, Skateboarding oder KI-Lerntipps. Die Balken zeigen <strong>interne Interessenwerte in Punkten</strong>. Die Balkenlänge dient dem Vergleich dieser Werte.</p><div class="sub-interest-list">${subbars}</div></div>
 <div class="panel"><h2>Deine letzten Interaktionen</h2><p>Diese Protokolle existieren nur im Arbeitsspeicher dieser Browserseite.</p><div class="timeline">${timeline}</div></div>
 <div class="privacy-strip">🛡️ <div><strong>Deine Auswertung wird nicht dauerhaft gespeichert.</strong><br>Keine Cookies, kein localStorage, kein sessionStorage und keine Datenbank. Beim Schließen <em>oder Neuladen</em> ist die Sitzung weg. Die Bereitstellung über GitHub Pages kann unabhängig davon technische Zugriffsprotokolle beim Hoster erzeugen.</div></div>
 <div class="panel"><h2>Was kannst du daraus schließen?</h2><p>Der Algorithmus kennt nicht deine wirklichen Interessen. Er bildet Vermutungen aus beobachtbarem Verhalten. Ob seine Empfehlungen deine Sicht einschränken, untersuchst du jetzt selbst.</p>${state.round<2?`<button class="primary-btn" data-nav="feed" type="button">Level 2: Weiter scrollen und Feed trainieren →</button>`:`<button class="primary-btn" data-nav="challenge" type="button">Level 4: Interessenprofil hinterfragen →</button>`}</div></section>`;
}
function topicName(id){return TOPICS.find(t=>t.id===id)?.label||'Unbekannt';}
function topicEmoji(id){return TOPICS.find(t=>t.id===id)?.emoji||'▫';}
const REFLECTION_TASKS=[
 ['profile','Hat dich FeedLab richtig eingeschätzt?','Wähle ein Thema aus deinem Interessenprofil. Passt es zu deinem tatsächlichen Interesse? Begründe deine Antwort.'],
 ['signal','Was kann dieselbe Handlung bedeuten?','Wähle ein erfasstes Signal oder eine Handlung aus deinem Feed. Nenne zwei verschiedene Gründe, warum jemand so handeln könnte.'],
 ['transfer','Wie kannst du deinen Feed vielfältiger machen?','Stell dir vor, ein echter Feed zeigt dir immer mehr zu diesem Thema. Was könntest du konkret tun, um auch andere Themen oder Sichtweisen zu sehen?']
];
function reflectionReady(){
 return REFLECTION_TASKS.every(([key])=>state.mission.answers[key].trim());
}
function renderChallenge(){
 const answers=state.mission.answers;
 const fields=REFLECTION_TASKS.map(([key,title,prompt])=>`<div class="panel"><h2><label for="reflection-${key}">${title}</label></h2><p id="prompt-${key}">${prompt}</p><textarea id="reflection-${key}" data-reflection-key="${key}" aria-describedby="prompt-${key}" class="observation-textarea" rows="3" maxlength="700" required>${esc(answers[key])}</textarea></div>`).join('');
 feedContainer.innerHTML=`<section class="section-page"><div class="kicker">LEVEL 4 · REFLEXION UND TRANSFER</div><h1>Hat dich der Feed richtig eingeschätzt?</h1><p class="lead">Vergleiche dein simuliertes Interessenprofil mit dem, was dich tatsächlich interessiert.</p><p>Du kannst jederzeit <button type="button" class="outline-btn" data-nav="insights">deine Auswertung öffnen</button>. Deine Antworten bleiben in dieser Sitzung erhalten.</p>${fields}<button type="button" class="primary-btn" data-action="mission-reveal" ${reflectionReady()?'':'disabled'}>Algorithmus aufdecken →</button></section>`;
}
function renderReveal(){
 const m=state.mission;
 if(m.phase!=='done')return;
 feedContainer.innerHTML=`<section class="section-page"><div class="kicker">AUFLÖSUNG · SO FUNKTIONIERT FEEDLAB</div><h1>Der Algorithmus ist kein Gedankenleser. 🧠</h1><p class="lead">Jetzt erfährst du, wie du mit deinen Aktionen die Empfehlungen beeinflusst hast. <strong>Das sind die wirklichen Regeln dieser App</strong> – keine Behauptung über die geheimen Systeme von Instagram.</p>
 <div class="hero-panel"><span class="kicker" style="color:#d7f9f6">EXPERIMENT BEENDET</span><h2>Du hast deinen Feed selbst trainiert.</h2><p>Die App hat aus sichtbarem Verhalten Interessenwerte geschätzt und daraus neue Beiträge ausgewählt. Welche davon für dich wirklich wichtig sind, weiß sie nicht.</p><h3>Deine Reflexion</h3>${REFLECTION_TASKS.map(([key,title])=>`<p><strong>${title}</strong><br>${esc(m.answers[key])}</p>`).join('')}</div>
 <div class="panel"><h2>1. So wertet FeedLab deine Handlungen aus</h2><div class="reveal-rules"><div><span>Unter 3 Sekunden ansehen</span><strong>0 Punkte</strong></div><div><span>Mindestens 3 Sekunden ansehen</span><strong>+1 Punkt</strong></div><div><span>Mindestens 5 Sekunden ansehen</span><strong>+2 Punkte insgesamt</strong></div><div><span>Erneut ansehen</span><strong>+2 Punkte einmalig</strong></div><div><span>Kommentare mindestens 3 Sekunden geöffnet</span><strong>+1 Punkt</strong></div><div><span>Kommentare mindestens 5 Sekunden geöffnet</span><strong>+2 Punkte insgesamt</strong></div><div><span>Like</span><strong>+3 Punkte</strong></div><div><span>Speichern</span><strong>+4 Punkte</strong></div><div><span>Teilen (simuliert)</span><strong>+3 Punkte</strong></div><div><span>„Weniger davon“</span><strong>−3 Punkte</strong></div><div><span>Thema bewusst entdecken</span><strong>+3 Punkte</strong></div><div><span>Entdeckungs-Beitrag öffnen</span><strong>+2 Punkte einmalig</strong></div></div><p class="hint-note">Die Zeit läuft nur, wenn mindestens 55 % der Bildfläche sichtbar sind und der Tab aktiv ist. Die 3- und 5-Sekunden-Werte werden nicht doppelt addiert. Wiederansehen zählt, nachdem ein bereits mindestens drei Sekunden betrachteter Beitrag verlassen und später erneut mindestens 1,5 Sekunden betrachtet wurde. Beim Kommentarfenster zählt ausschließlich dessen aktive Öffnungsdauer; das ist kein Beweis dafür, dass der Text gelesen wurde.</p></div>
 <div class="panel"><h2>2. So wird ein neuer Feed berechnet</h2><p>Jedes Signal verändert einen Interessenwert für das <strong>Oberthema</strong> (z. B. Tiere) und stärker für das <strong>Unterthema</strong> (z. B. Katzen). Der nächste Feed nutzt diese Werte als Gewichtung. Der erste Feed besteht aus 30 ausgewogenen Beiträgen (pro Thema drei bis vier) und wird noch nicht personalisiert. Danach folgen drei automatisch geladene Gruppen mit je sechs ungesehenen Beiträgen. Fünf der sechs Empfehlungen folgen den gewichteten Interessen, eine bezieht bewusst schwächer vertretene Themen ein. Die Auswahl enthält weiterhin Zufall.</p><pre class="code-example"><code>// Vereinfacht, aber entsprechend unserem Programm:
interessenwert[thema] += punkte * 0.65
unterinteresse[unterthema] += punkte

gewicht = themaInteresse ** 1.28
        * unterthemaInteresse ** 1.25
// pro Sechsergruppe: 5 gewichtete + 1 andere Perspektive

// Ein höheres Gewicht bedeutet:
// Dieser Beitrag wird wahrscheinlicher ausgewählt.
// Es gibt keine Garantie für einen bestimmten Post.</code></pre><a class="source-link" href="app.js" target="_blank" rel="noopener">Den vollständigen JavaScript-Quellcode ansehen ↗</a><p class="hint-note">Im echten Quellcode werden Interessenwerte gegen negative/zu kleine Werte abgesichert; außerdem fließt der Unterthemenwert mit einem Faktor von 0,70 ein. Die 18 Empfehlungen verwenden ausschließlich bisher ungesehene Beiträge aus dem 94 Posts umfassenden Inhaltspool. Das Modell wird schon während der ersten 30 Beiträge trainiert, die Auswahl jedoch erst anschließend personalisiert.</p></div>
 <div class="panel"><h2>3. Was ist eine Filterblase?</h2><p>Eine <strong>Filterblase</strong> entsteht, wenn personalisierte Auswahlmechanismen bestimmte Interessen, Informationen oder Perspektiven besonders oft anzeigen und andere seltener sichtbar werden. Der Feed wirkt dann so, als gäbe es vor allem das, was dir ohnehin schon angezeigt wird.</p><div class="danger-grid"><div>🔁 <strong>Einseitigkeit</strong><p>Du siehst viele ähnliche Inhalte und weniger alternative Perspektiven.</p></div><div>🧩 <strong>Verzerrtes Weltbild</strong><p>Du könntest die Häufigkeit oder Beliebtheit einer Meinung überschätzen.</p></div><div>⚠️ <strong>Desinformation</strong><p>Wenn fragwürdige Beiträge oft erscheinen, können sie vertrauter oder glaubwürdiger wirken.</p></div><div>🗯️ <strong>Polarisierung</strong><p>Ständige Wiederholung extremer Positionen kann Konflikte verstärken – aber nicht jeder Feed führt dazu.</p></div></div><p><strong>Wichtig:</strong> Filterblase und Echokammer sind nicht dasselbe. Eine Filterblase beschreibt eine personalisierte Auswahl von Informationen; eine Echokammer entsteht vor allem, wenn Menschen oder Gruppen gegenseitig dieselben Ansichten bestätigen und andere Sichtweisen abwerten.</p></div>
 <div class="panel"><h2>4. Was kannst du dagegen tun?</h2><div class="tip-list"><p>✓ Unterschiedliche und verlässliche Quellen gezielt aufrufen</p><p>✓ Andere Perspektiven und Themen bewusst entdecken</p><p>✓ Aussagen prüfen, bevor du sie teilst</p><p>✓ Empfehlungen kritisch hinterfragen und Einstellungen nutzen</p></div><div class="callout"><strong>Übertrage das Ergebnis auf einen echten Feed.</strong><p>Woran würdest du erkennen, dass dir ein Feed wichtige Perspektiven seltener zeigt? Nenne einen konkreten Hinweis und beschreibe, wie du ihn mit einer zweiten Quelle prüfen würdest.</p><p>Viele Sportbeiträge zeigen, dass ein Thema häufig vorkommt. Überlege bei einem kontroversen Thema zusätzlich, welche begründeten Sichtweisen fehlen könnten.</p></div><p><strong>Deine Erkenntnis:</strong> Ein Algorithmus kann Interessen aus deinem Verhalten ableiten. Was er dir zeigt, ist aber nie die ganze Wirklichkeit.</p><button class="outline-btn" type="button" data-nav="insights">Meine persönliche Auswertung erneut ansehen</button> <button class="outline-btn" type="button" data-nav="challenge">Meine Reflexion ansehen</button></div><div class="privacy-strip">🔒 <div><strong>Deine Daten bleiben nur im Arbeitsspeicher.</strong><br>Schließt oder lädst du die Seite neu, verschwinden dein Verlauf, dein Interessenprofil und die Diagrammwerte. Es wird kein persönlicher Datensatz heruntergeladen.</div></div></section>`;
}
function updateSide(){const cnt=document.getElementById('rightSignals');if(!cnt)return;cnt.innerHTML=`<span><small>Erkannte Signale</small><br/><strong>${state.signals.length}</strong></span><span style="font-size:22px">↗</span>`;document.getElementById('rightTopics').innerHTML=[...TOPICS].sort((a,b)=>state.weights[b.id]-state.weights[a.id]).slice(0,4).map(t=>`<div class="topic-mini-row"><div class="topic-mini-label"><span>${t.emoji} ${t.short}</span><b title="Anteil am gesamten internen Themengewicht">${weightPct(t.id)} % Gewichtsanteil</b></div><div class="track"><div style="width:${weightPct(t.id)}%"></div></div></div>`).join('')}

// Kommentare werden nur bei einem tatsächlich geöffneten Kommentarfenster und
// sichtbarem Tab gemessen. Kein Klick-Bonus, keine dauerhafte Speicherung.
function commentInfo(id){return state.commentWatchData[id]||(state.commentWatchData[id]={ms:0,three:false,five:false});}
function stopCommentWatch(){
 if(commentWatch){commentTick();commentWatch=null;}
 if(commentWatchInterval!==null){clearInterval(commentWatchInterval);commentWatchInterval=null;}
}
function commentTick(){
 if(!commentWatch)return;
 const now=performance.now();
 if(document.hidden||!document.querySelector('.comment-modal-content')){commentWatch.last=now;return;}
 const dt=Math.max(0,Math.min(300,now-commentWatch.last));commentWatch.last=now;
 const c=commentInfo(commentWatch.id);c.ms+=dt;
 const post=getPost(commentWatch.id);if(!post)return;
 if(!c.three&&c.ms>=3000){c.three=true;recordPostSignal(post,'Kommentare 3 Sekunden angesehen',1,'comments');showToast('💬 Kommentarbereich: 3 Sekunden Interesse');}
 if(!c.five&&c.ms>=5000){c.five=true;recordPostSignal(post,'Kommentare 5 Sekunden angesehen (+1, gesamt +2)',1,'comments');showToast('💬 Kommentarbereich: 5 Sekunden Interesse');}
 const label=document.querySelector('[data-comment-watch-label]');
 if(label)label.textContent=c.five?'5 Sekunden Kommentarinteresse erkannt':c.three?'3 Sekunden Kommentarinteresse erkannt':'Kommentare lesen – ab 3 Sekunden zählt Interesse';
}
function startCommentWatch(id){
 stopCommentWatch();commentWatch={id,last:performance.now()};commentWatchInterval=setInterval(commentTick,140);
}
function openModal(title,body,watchPostId=null){stopCommentWatch();stopModalWatch();stopAllWatches();const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-wrap"><div class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" type="button" aria-label="Schließen">×</button></div>${body}</div></div>`;root.querySelector('.modal-close').focus();if(watchPostId)startModalWatch(watchPostId);}
function closeModal(){if(!sessionStarted)return;stopCommentWatch();stopModalWatch();document.getElementById('modalRoot').innerHTML='';if(state.view==='feed'){scanVisiblePosts();if(watchInterval===null)watchInterval=setInterval(tickVisiblePosts,160);if(nearFeedEnd())queueFeedAppend();}}
function openComments(p){
 const data=commentInfo(p.id);
 const status=data.five?'5 Sekunden Kommentarinteresse erkannt':data.three?'3 Sekunden Kommentarinteresse erkannt':'Kommentare lesen – ab 3 Sekunden zählt Interesse';
 const rows=p.comments.map((c,i)=>`<div class="comment-entry"><div class="comment-avatar" aria-hidden="true">${['💬','😊','🎬','✨','🎮','🌿'][i%6]}</div><div class="comment-content"><strong>${c[0]}</strong> <span>${c[1]}</span><small>vor ${i<7?i+1:i*2} Std. · Antworten</small></div><span class="comment-heart" aria-hidden="true">♡</span></div>`).join('');
 openModal('💬 Kommentare',`<div class="comment-modal-content"><div class="comment-summary"><strong>${p.comments.length} fiktive Kommentare</strong><span>zu ${p.username}</span></div><div class="comment-dwell-status" data-comment-watch-label>${status}</div><div class="comment-list">${rows}</div><p class="hint-note">${state.observation.done?'Diese Gespräche sind erfunden. Die App misst nur, wie lange das Kommentarfenster im aktiven Tab geöffnet ist – nicht, ob du tatsächlich liest.':'Diese Gespräche sind erfunden.'}</p></div>`);
 startCommentWatch(p.id);
}

function help(){
 if(!state.observation.done){openModal('Willkommen bei FeedLab', `<p>Nutze den Feed so, wie du normalerweise ein soziales Netzwerk nutzen würdest. Alle Inhalte und Accounts sind fiktiv.</p><p>Nutzungsaktivitäten werden zu Lernzwecken erfasst und bleiben im Arbeitsspeicher dieses Browser-Tabs. Beim Schließen oder Neuladen werden sie gelöscht.</p>`);return;}

 openModal('So funktioniert FeedLab',`<p>Du erkundest einen <strong>fiktiven Social-Media-Feed</strong> mit 94 Posts. Die App erkennt, ob du Beiträge länger ansiehst, Kommentarbereiche länger geöffnet hältst, likst, speicherst, erneut betrachtest oder weniger davon sehen möchtest.</p><p>Du siehst zunächst 30 gemischte Beiträge. Danach werden automatisch drei personalisierte Gruppen mit jeweils sechs Beiträgen geladen. Nach insgesamt 48 Beiträgen endet Level 1. Halte in Level 2 zuerst deine eigene Beobachtung fest und untersuche anschließend deine persönliche Auswertung in Level 3 und führe anschließend die Reflexion zum Interessenprofil in Level 4 durch. <strong>Erst am Schluss</strong> wird der Programmcode mit den genauen Gewichtungen offengelegt.</p><p><strong>Datenschutz:</strong> Kein Login, kein externer Trackingdienst, keine Cookies und keine Speicherdienste. Dein Interessenprofil liegt nur während dieser geöffneten Seite im Arbeitsspeicher. Schließen oder Neuladen löscht es. Hosting-Anbieter können technische Zugriffsprotokolle führen.</p>`);
}
function setupEvents(){document.getElementById('startFeed').addEventListener('click',startFeed);document.addEventListener('click',event=>{
 if(!sessionStarted)return;
 const nav=event.target.closest('[data-nav]');if(nav){setView(nav.dataset.nav);return;}
 const story=event.target.closest('.story-btn[data-topic]');if(story){selectedTopic=story.dataset.topic;setView('discover');return;}
 const filter=event.target.closest('[data-filter]');if(filter){selectedTopic=filter.dataset.filter;renderDiscover();return;}
 const action=event.target.closest('[data-action]');if(!action)return;
 if(action.dataset.action==='observation-finish'){if(!canFinishObservation())return;state.observation.done=true;setView('insights');return;}
 if(action.dataset.action==='mission-reveal'){
  if(state.view!=='challenge'||!reflectionReady())return;
  state.mission.phase='done';setView('reveal');return;
 }
 if(action.dataset.action==='close-modal'){closeModal();return;}
 if(action.dataset.action==='explore-post'){
   const p=getPost(action.dataset.id);if(!p)return;
   if(!state.discoveredPosts.has(p.id)){
     state.discoveredPosts.add(p.id);
     recordSignal(p.topic,'Gezielt Beitrag entdeckt: '+p.subtopic,2,'discover',p.subtopic,p.id);
   }
   openModal('Entdeckt: '+p.sub,`<img src="${p.image}" data-watch-media="${p.id}" alt="${p.sub}" style="width:100%;border-radius:11px;max-height:360px;object-fit:cover"/><p class="post-watch dwell-label" data-watch-label="${p.id}">${watchLabel(p.id)}</p><p><strong>${p.username}</strong> ${p.caption}</p>${p.question?`<p>${p.question}</p>`:''}<div class="modal-actions"><button class="outline-btn" data-action="comments" data-id="${p.id}" type="button">💬 ${p.comments.length} Kommentare</button><button class="outline-btn" data-action="like" data-id="${p.id}" type="button">❤️ Like</button><button class="outline-btn" data-action="save" data-id="${p.id}" type="button">🔖 Speichern</button><button class="outline-btn" data-action="skip" data-id="${p.id}" type="button">↘ Weniger davon</button></div><p class="hint-note">Die Interaktionen wirken auf deinen Lernalgorithmus; sie werden nicht an echte Accounts übertragen.</p><button class="primary-btn" data-action="close-modal" type="button">Weiterstöbern</button>`,p.id);return;
 }

 if(action.dataset.action==='explore'){
   const topic=action.dataset.topic;
   if(state.exploredTopics.has(topic))return;
   state.exploredTopics.add(topic);
   recordSignal(topic,'Bewusst neues Thema entdeckt',3,'discover');
   showToast(`${topicEmoji(topic)} Thema ${topicName(topic)} bewusst entdeckt`);
   action.disabled=true;action.textContent='✓ Interesse gezeigt';return;
 }

 if(action.dataset.id){
   performAction(action.dataset.action,action.dataset.id);
   if(state.view==='discover'&&['like','save','skip'].includes(action.dataset.action)){
     if(action.dataset.action==='like')action.textContent=state.likes.has(action.dataset.id)?'♥ Gefällt dir':'❤️ Like';
     if(action.dataset.action==='save')action.textContent=state.saves.has(action.dataset.id)?'✓ Gespeichert':'🔖 Speichern';
     if(action.dataset.action==='skip'){action.textContent='✓ Weniger davon';action.disabled=true;}
   }
 }

 });document.getElementById('modalRoot').addEventListener('click',e=>{if(e.target.classList.contains('modal-wrap'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
 document.getElementById('sideReset').addEventListener('click',()=>{openModal('Neues Experiment?',`<p>Damit werden alle bisherigen Interaktionen und die aktuelle Feed-Runde zurückgesetzt. Du beginnst wieder mit einem ausgewogenen Startfeed.</p><div style="display:flex;gap:9px;margin-top:16px"><button class="primary-btn" id="confirmReset" type="button">Ja, neu beginnen</button><button class="outline-btn" data-action="close-modal" type="button">Abbrechen</button></div>`);document.getElementById('confirmReset').addEventListener('click',()=>{closeModal();reset()})});
 document.addEventListener('input',e=>{
   if(e.target?.id==='observationNotes'){
     state.observation.notes=e.target.value;
     const finish=feedContainer.querySelector('[data-action="observation-finish"]');
     if(finish)finish.disabled=!canFinishObservation();
   }
   const key=e.target?.dataset?.reflectionKey;
   if(state.view==='challenge'&&Object.hasOwn(state.mission.answers,key)){
     state.mission.answers[key]=e.target.value;
     const reveal=feedContainer.querySelector('[data-action="mission-reveal"]');
     if(reveal)reveal.disabled=!reflectionReady();
   }
 });
 document.addEventListener('change',e=>{
   if(e.target?.name==='feed-observation'&&state.view==='reflection'){
     state.observation.answer=e.target.value;
     const finish=feedContainer.querySelector('[data-action="observation-finish"]');
     if(finish)finish.disabled=!canFinishObservation();
   }
 });
 document.getElementById('mobileHelp').addEventListener('click',help);
 document.addEventListener('visibilitychange',()=>{
   if(!sessionStarted)return;
   if(document.hidden){stopAllWatches();if(modalWatch)modalWatch.lastTime=performance.now();if(commentWatch)commentWatch.last=performance.now();}
   else if(state.view==='feed'&&!document.getElementById('modalRoot').hasChildNodes()){
     scanVisiblePosts();if(watchInterval===null)watchInterval=setInterval(tickVisiblePosts,160);
     if(nearFeedEnd())queueFeedAppend();
   }
 });
}
state=initialState();setupEvents();
